param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-parse-style-overloads-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$delegates=@{};$span=[ReadOnlySpan``1].MakeGenericType([char]);$asSpan=[MemoryExtensions].GetMethod('AsSpan',[type[]]@([string]));foreach($route in @('string','chars')){$types=[type[]]@([string],[Globalization.NumberStyles]);if($route -eq 'chars'){$types[0]=$span;$types=[type[]]@($span,[Globalization.NumberStyles],[IFormatProvider])};$method=[decimal].GetMethod('Parse',$types);$dm=[Reflection.Emit.DynamicMethod]::new('ParseStyleOnly',[decimal],[type[]]@([string],[int]));$il=$dm.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);if($route -eq 'chars'){$il.Emit([Reflection.Emit.OpCodes]::Call,$asSpan)};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);if($route -eq 'chars'){$il.Emit([Reflection.Emit.OpCodes]::Ldnull)};$il.Emit([Reflection.Emit.OpCodes]::Call,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$delegates[$route]=$dm.CreateDelegate([Func[string,int,decimal]])}
$rows=[Collections.Generic.List[object]]::new();foreach($style in $plan.styles){foreach($text in $plan.texts){foreach($route in @('string','chars')){$arguments=[object[]]::new(2);$arguments[0]=$text;$arguments[1]=[int]$style;try{$value=[decimal]$delegates[$route].DynamicInvoke($arguments);$result=[ordered]@{ok=$true;bits=[decimal]::GetBits($value)}}catch{$result=Failure $_};$rows.Add([ordered]@{style=$style;text=$text;route=$route;result=$result})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Decimal style-only Parse: $($rows.Count) calls"
